const cursor=document.createElement('div');cursor.className='story-cursor';cursor.innerHTML='<span>SCROLL</span><svg viewBox="0 0 60 60"><circle cx="30" cy="30" r="27"/></svg>';document.body.append(cursor);let cx=innerWidth/2,cy=innerHeight/2,tx=cx,ty=cy;document.addEventListener('pointermove',e=>{mx=e.clientX/innerWidth*2-1;my=e.clientY/innerHeight*2-1;tx=e.clientX;ty=e.clientY;cursor.classList.add('active');const hit=e.target.closest('button,a');cursor.classList.toggle('link',!!hit);cursor.querySelector('span').textContent=e.target.closest('.portal-art')?'HOLD':e.target.closest('.bottle3d')?'CHOISIR':e.target.closest('.pour-stage')?'VERSER':hit?'↗':'SCROLL';},{passive:true});document.addEventListener('pointerout',e=>{if(!e.relatedTarget)cursor.classList.remove('active')});
for(const id of ['story','portal','ascension']){const section=document.getElementById(id);const stage=document.createElement('div');stage.className='cinema-stage';while(section.firstChild)stage.append(section.firstChild);section.append(stage);section.classList.add('cinematic');animated.push({section,stage,p:0});}
// Additional hall: columns separate from the bottles and move in perspective.
