function bottle(n){let wrap=document.createElement('button');wrap.className='bottle3d';wrap.dataset.flavor=n;wrap.setAttribute('aria-label',['Choisir Bleu Pigment de nuit','Choisir Vert Pigment de nuit','Choisir Or Pigment des quais'][n]);wrap.style.setProperty('--bottle-color',['#73b5d6','#9fce96','#e7d47a'][n]);wrap.innerHTML='<span class="bottle-spinner"><span class="cylinder"></span><span class="cork"></span><span class="bottle-top"></span><span class="ink-label"><small>NOTTURNO N° 0'+(n+1)+'</small><b>Atelier<br><i>Nocturne</i></b><small>ENCRES DE NUIT<br>SÉRIE DU PORT</small></span></span>';let cylinder=wrap.querySelector('.cylinder');for(let k=0;k<24;k++){const face=document.createElement('span');face.className='bottle-face';face.style.setProperty('--face',k);face.style.setProperty('--shade',Math.max(.25,Math.cos(k/24*Math.PI*2)*.4+.6));cylinder.append(face)}wrap.addEventListener('click',()=>{if(wrap.classList.contains('product-bottle3d'))return;choose(n);document.querySelectorAll('.bottle3d').forEach((b,i)=>{b.classList.toggle('chosen',n===i);b.classList.toggle('dismissed',n!==i)});burst(wrap);setTimeout(()=>document.querySelectorAll('.bottle3d').forEach(b=>b.classList.remove('dismissed')),1100)});return wrap}
const shelf=document.createElement('div');shelf.className='bottle-shelf';for(let i=0;i<3;i++)shelf.append(bottle(i));choice.append(shelf);const stageProduct=document.querySelector('.bottle-wrap');const productBottle=bottle(0);productBottle.removeAttribute('data-flavor');productBottle.setAttribute('aria-label','Faire tourner la bouteille');productBottle.classList.add('product-bottle3d');stageProduct.querySelector('.bottle').hidden=true;stageProduct.append(productBottle);let angle=0,drag=false,dragX=0;productBottle.addEventListener('pointerdown',e=>{drag=true;dragX=e.clientX;productBottle.setPointerCapture(e.pointerId)});productBottle.addEventListener('pointermove',e=>{if(drag){angle+=(e.clientX-dragX)*1.5;dragX=e.clientX;productBottle.style.setProperty('--spin',angle+'deg')}});productBottle.addEventListener('pointerup',()=>drag=false);productBottle.addEventListener('pointercancel',()=>drag=false);productBottle.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();angle+=e.key==='ArrowLeft'?-30:30;productBottle.style.setProperty('--spin',angle+'deg')}});new MutationObserver(()=>{productBottle.style.setProperty('--bottle-color',getComputedStyle(root).getPropertyValue('--accent'));productBottle.querySelector('.ink-label>small').textContent=document.querySelector('.bottle-no').textContent}).observe(document.querySelector('.bottle-no'),{childList:true});
function burst(target){if(reduced)return;const rect=target.getBoundingClientRect();for(let i=0;i<34;i++){const petal=document.createElement('span');petal.className='petal burst';petal.style.left=rect.left+rect.width/2+'px';petal.style.top=rect.top+rect.height/2+'px';document.body.append(petal);const a=Math.random()*Math.PI*2,d=90+Math.random()*220;petal.animate([{transform:'translate(0,0) rotate(0deg)',opacity:1},{transform:`translate(${Math.cos(a)*d}px,${Math.sin(a)*d}px) rotate(${Math.random()*720}deg)`,opacity:0}],{duration:900+Math.random()*700,easing:'cubic-bezier(.15,.7,.3,1)'}).onfinish=()=>petal.remove()}}
// Floating, colour-linked petals in the beam of light.
const bloom=document.createElement('div');bloom.className='petal-field';document.querySelector('.ascension-art').append(bloom);for(let i=0;i<30;i++){const p=document.createElement('span');p.className='petal';p.style.setProperty('--x',Math.random()*100+'%');p.style.setProperty('--delay',-Math.random()*12+'s');p.style.setProperty('--duration',8+Math.random()*9+'s');p.style.setProperty('--r',Math.random()*360+'deg');bloom.append(p)}
// Independent hand layer over a drawn wall: dragging really moves the hand.
