// GPU-rendered ink: an actual fragment shader, with image fallback if WebGL is unavailable.
const renderers=[];const fragment=`precision mediump float; varying vec2 v; uniform sampler2D tex;uniform vec2 viewport;uniform vec2 imageSize;uniform vec2 pointer;uniform float time;uniform float travel;uniform float power;float rand(vec2 p){return fract(sin(dot(p,vec2(12.9898,78.233)))*43758.5453);}void main(){float ar=viewport.x/viewport.y;float ia=imageSize.x/imageSize.y;vec2 uv=v;uv=(uv-.5)*vec2(ar>ia?1.:ar/ia,ar>ia?ia/ar:1.)+.5;float zoom=1.03+travel*.13;uv=(uv-.5)/zoom+.5;uv+=pointer*.013;float beat=floor(time*8.);float jitter=(rand(vec2(beat,floor(uv.y*260.)))-.5)*.0015;uv.x+=jitter;float d=distance(v,pointer*.2+.5);uv+=normalize(v-.5+vec2(.001))*sin(d*48.-time*3.)*.002*power;vec4 c=texture2D(tex,clamp(uv,vec2(.006),vec2(.994)));float grain=(rand(v*viewport+beat)-.5)*.025;c.rgb+=grain;gl_FragColor=c;}`;
